(x, y, t) => {
  const cx = 240, cy = 120;
  const wx1 = Math.sin(x*0.02+t*0.3)*15+Math.cos(y*0.015-t*0.2)*10;
  const wy1 = Math.cos(y*0.02-t*0.25)*15+Math.sin(x*0.018+t*0.35)*10;
  const wx2 = Math.sin((x+wx1)*0.035+t*0.5)*8+Math.cos((y+wy1)*0.03-t*0.4)*6;
  const wy2 = Math.cos((y+wy1)*0.03-t*0.45)*8+Math.sin((x+wx1)*0.025+t*0.55)*6;
  const sx = x+wx1+wx2, sy = y+wy1+wy2;
  const src = [
    [160+Math.sin(t*0.6)*100,80+Math.cos(t*0.4)*50,0.08,2.0,1.0],
    [320+Math.cos(t*0.5)*100,160+Math.sin(t*0.7)*50,0.1,1.7,0.9],
    [240+Math.sin(t*0.3+2)*140,120+Math.cos(t*0.5+1)*90,0.06,2.3,1.1],
    [120+Math.cos(t*0.8+1)*80,180+Math.sin(t*0.6+3)*60,0.12,1.5,0.8],
    [360+Math.sin(t*0.4+4)*90,60+Math.cos(t*0.9+2)*70,0.07,2.6,1.2],
    [240+Math.cos(t*0.35+5)*120,200+Math.sin(t*0.55)*80,0.09,1.9,1.0],
    [80+Math.sin(t*0.45+3)*70,40+Math.cos(t*0.65+4)*50,0.11,2.1,0.7],
    [400+Math.cos(t*0.55+2)*60,200+Math.sin(t*0.75+1)*70,0.05,2.8,1.3],
    [200+Math.sin(t*0.7)*110,220+Math.cos(t*0.3)*60,0.13,1.4,0.85],
    [300+Math.cos(t*0.25+6)*90,100+Math.sin(t*0.85)*80,0.085,2.2,1.05]
  ];
  let aS=0,iS=0,tS=0;
  for(const[sX,sY,f,sp,amp]of src){
    const d=Math.sqrt((sx-sX)**2+(sy-sY)**2);
    aS+=Math.sin(d*f-t*sp)*amp;
    iS+=Math.sin(d*f*0.7+t*sp*0.6+1.5)*amp;
    tS+=Math.sin(d*f*1.3-t*sp*0.4+2.8)*amp*0.5;
  }
  const act=aS/10,inh=iS/10,ter=tS/10;
  let fbm=0,fa=0.5;
  for(let i=0;i<4;i++){const s=1<<i;fbm+=fa*(Math.sin(sx*0.04*s+sy*0.025*s+t*(0.5+i*0.3))*0.5+0.5);fa*=0.5;}
  const bg=(fbm-0.5)*2;
  const dist=Math.sqrt((sx-cx)**2+(sy-cy)**2),ang=Math.atan2(sy-cy,sx-cx);
  const spiral=(Math.sin(dist*0.05-ang*3-t*1.5)+Math.sin(dist*0.04+ang*4-t*1.2))*0.3+Math.sin(dist*0.03-ang*6+t*0.8)*0.2+Math.sin(dist*0.07+ang*2-t*2)*0.15;
  const reaction=Math.tanh((act-inh*0.6+bg*0.25+spiral+ter*0.3)*2.0);
  const cellX=Math.sin(sx*0.15)*Math.sin(sy*0.15)+Math.sin(sx*0.08+t*0.7)*Math.cos(sy*0.12-t*0.5)*0.5+Math.sin((sx+sy)*0.1+t)*0.3;
  const cell=Math.tanh(cellX*1.8)*0.3;
  const turb=Math.sin(sx*0.3+Math.sin(sy*0.2+t)*2+t*1.5)*Math.cos(sy*0.25+Math.sin(sx*0.15-t)*1.5)*0.15;
  const blend=reaction*0.6+cell*0.2+turb*0.2,v=blend*0.5+0.5;
  const pal=[[5,12,52],[10,45,85],[15,90,120],[20,150,135],[60,185,110],[170,195,65],[230,190,50],[235,140,55],[215,90,60],[175,50,65],[120,30,60],[70,20,55],[5,12,52]];
  const idx=v*(pal.length-1),i=Math.min(idx|0,pal.length-2),f=idx-i;
  const lum=0.75+Math.sin(reaction*Math.PI)*0.25;
  const edge=Math.abs(reaction)>0.75?1.2:Math.abs(reaction)>0.5?1.08:1.0;
  const glow=Math.max(0,reaction-0.5)*0.4;
  return[Math.min(255,((pal[i][0]+(pal[i+1][0]-pal[i][0])*f)*lum*edge+glow*60)|0),Math.min(255,((pal[i][1]+(pal[i+1][1]-pal[i][1])*f)*lum*edge+glow*40)|0),Math.min(255,((pal[i][2]+(pal[i+1][2]-pal[i][2])*f)*lum*edge+glow*20)|0)];
}
